        };
    }

    internal static int WriteJoin(GraphBuilder graph, Join value)
    {
        return value.Value switch
        {
            JoinEntity item => WriteJoinEntity(graph, item),
            JoinSubquery item => WriteJoinSubquery(graph, item),
            _ => throw GraphBuilder.Empty("Join"),
        };
    }

    internal static Join ReadJoin(IReadNode node)
    {
        return node.Label switch
        {
            "JoinEntity" => new Join(ReadJoinEntity(node)),
            "JoinSubquery" => new Join(ReadJoinSubquery(node)),
            _ => throw GraphReads.NotACase(node, "Join"),
        };
    }

    internal static void WritePaginationSkip(
        GraphBuilder graph,
        int node,
        string name,
        string type,
        PaginationSkip value
    )
    {
        switch (value.Value)
        {
            case long item:
                graph.Set(node, name, item);
                break;
            case ParamInteger item:
                graph.Link(node, type, WriteParamInteger(graph, item));
                break;
            default:
                throw GraphBuilder.Empty("PaginationSkip");
        }
    }

    internal static PaginationSkip ReadPaginationSkip(
        IReadNode node,
        string name,
        string type
    )
    {
        if (GraphReads.Has(node, name))
        {
            return new PaginationSkip(GraphReads.Integer(node, name));
        }

        IReadNode child = GraphReads.Child(node, type);
        return child.Label switch
        {
            "ParamInteger" => new PaginationSkip(ReadParamInteger(child)),
            _ => throw GraphReads.NotACase(child, "PaginationSkip"),
        };
    }

