    internal static int WritePureQLQuery(GraphBuilder graph, PureQLQuery value)
    {
        return value.Value switch
        {
            MainGroupedQueryWithoutPagination item => WriteMainGroupedQueryWithoutPagination(graph, item),
            MainGroupedQueryWithPagination item => WriteMainGroupedQueryWithPagination(graph, item),
            MainTotalQuery item => WriteMainTotalQuery(graph, item),
            MainPlainQueryWithoutPagination item => WriteMainPlainQueryWithoutPagination(graph, item),
            MainPlainQueryWithPagination item => WriteMainPlainQueryWithPagination(graph, item),
            _ => throw GraphBuilder.Empty("PureQLQuery"),
        };
    }

    internal static PureQLQuery ReadPureQLQuery(IReadNode node)
    {
        return node.Label switch
        {
            "MainGroupedQueryWithoutPagination" =>
                new PureQLQuery(ReadMainGroupedQueryWithoutPagination(node)),
            "MainGroupedQueryWithPagination" =>
                new PureQLQuery(ReadMainGroupedQueryWithPagination(node)),
            "MainTotalQuery" => new PureQLQuery(ReadMainTotalQuery(node)),
            "MainPlainQueryWithoutPagination" =>
                new PureQLQuery(ReadMainPlainQueryWithoutPagination(node)),
            "MainPlainQueryWithPagination" =>
                new PureQLQuery(ReadMainPlainQueryWithPagination(node)),
