        };
    }

    internal static int WriteQuery(GraphBuilder graph, Query value)
    {
        return value.Value switch
        {
            GroupedQueryWithoutPaginationWithoutOrderBy item => WriteGroupedQueryWithoutPaginationWithoutOrderBy(graph, item),
            GroupedQueryWithoutPaginationWithOrderBy item => WriteGroupedQueryWithoutPaginationWithOrderBy(graph, item),
            GroupedQueryWithPagination item => WriteGroupedQueryWithPagination(graph, item),
            TotalQuery item => WriteTotalQuery(graph, item),
            PlainQueryWithoutPaginationWithoutOrderBy item => WritePlainQueryWithoutPaginationWithoutOrderBy(graph, item),
            PlainQueryWithoutPaginationWithOrderBy item => WritePlainQueryWithoutPaginationWithOrderBy(graph, item),
            PlainQueryWithPagination item => WritePlainQueryWithPagination(graph, item),
            _ => throw GraphBuilder.Empty("Query"),
        };
    }

    internal static Query ReadQuery(IReadNode node)
    {
        return node.Label switch
        {
            "GroupedQueryWithoutPaginationWithoutOrderBy" =>
                new Query(ReadGroupedQueryWithoutPaginationWithoutOrderBy(node)),
            "GroupedQueryWithoutPaginationWithOrderBy" =>
                new Query(ReadGroupedQueryWithoutPaginationWithOrderBy(node)),
            "GroupedQueryWithPagination" =>
                new Query(ReadGroupedQueryWithPagination(node)),
            "TotalQuery" => new Query(ReadTotalQuery(node)),
            "PlainQueryWithoutPaginationWithoutOrderBy" =>
                new Query(ReadPlainQueryWithoutPaginationWithoutOrderBy(node)),
            "PlainQueryWithoutPaginationWithOrderBy" =>
                new Query(ReadPlainQueryWithoutPaginationWithOrderBy(node)),
            "PlainQueryWithPagination" => new Query(ReadPlainQueryWithPagination(node)),
            _ => throw GraphReads.NotACase(node, "Query"),
